// Chooses between the 3D world and the classic site, adds the switch to the
// toolbar, and loads the 3D code only when it is wanted.
import "./island.css";
import { parseGuest, checkGuest } from "./guest.js";
import { pullGameSaves, flushGameSaves } from "./sync.js";

const guestInfo = parseGuest();

// in the 3D world the page is a little taller than the screen (see island.css);
// it never stays scrolled, except while typing lets the keyboard move it
function keepTop() {
  if (!document.documentElement.classList.contains("g3d-on") || !window.scrollY) return;
  if (document.activeElement?.matches?.("input, textarea, [contenteditable='true']")) return;
  window.scrollTo(0, 0);
}
window.addEventListener("scroll", keepTop, { passive: true });
document.addEventListener("focusout", () => setTimeout(keepTop, 50));

const MODE_KEY = "tdd3d.mode";
let game = null;
let starting = null;

function webglOK() {
  try {
    const c = document.createElement("canvas");
    return Boolean(c.getContext("webgl2") || c.getContext("webgl"));
  } catch {
    return false;
  }
}

function readMode() {
  const param = new URLSearchParams(location.search).get("mode");
  if (param === "2d" || param === "3d") return param;
  // the classic site is the main page; the 3D world opens from its button
  return "2d";
}

function saveMode(mode) {
  try {
    localStorage.setItem(MODE_KEY, mode);
  } catch {}
}

const switchBtn = document.createElement("button");
switchBtn.type = "button";
switchBtn.className = "soft-btn profile-icon-btn g3d-switch";
switchBtn.addEventListener("click", () => (game || starting ? exit() : enter()));

function syncSwitch() {
  const on = Boolean(game || starting);
  switchBtn.textContent = on ? "2D" : "3D";
  switchBtn.title = on ? "back to the classic site" : "enter the 3D world";
  switchBtn.setAttribute("aria-label", switchBtn.title);
}

// ---- the portal between 2D and 3D -------------------------------------------------------
// a pastel circle bursts out of the switch button and covers the screen while one world
// packs away and the other unpacks, then melts away with a little heart
const reduceMotion = () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
const wait = (ms) => new Promise((res) => setTimeout(res, ms));
// the doorway between the diary and the island: a little floating island drifting in its
// own sky, the words appearing letter by letter, and what's happening while it loads
const ISLAND_SVG = `<svg viewBox="0 0 220 170" aria-hidden="true">
  <g class="pi-isle">
    <path class="pi-under" d="M28 92 Q110 182 192 92 Z"/>
    <path class="pi-rock" d="M62 104 L78 128 L90 110 L104 146 L118 112 L132 134 L146 108 L160 120 L170 100 Z"/>
    <path class="pi-fall" d="M150 96 L154 96 L156 156 L148 156 Z"/>
    <ellipse class="pi-grass" cx="110" cy="92" rx="84" ry="14"/>
    <path class="pi-trunk" d="M106 92 Q108 70 104 56 L112 56 Q110 72 114 92 Z"/>
    <path class="pi-heart" d="M109 62 C88 46 84 22 100 18 C106 16 109 22 109 26 C109 22 112 16 118 18 C134 22 130 46 109 62 Z"/>
    <rect class="pi-house" x="40" y="74" width="20" height="14" rx="2"/>
    <path class="pi-roof" d="M36 76 L50 64 L64 76 Z"/>
    <circle class="pi-lamp" cx="160" cy="80" r="3"/>
    <path class="pi-tree" d="M168 90 L176 66 L184 90 Z"/>
    <path class="pi-tree" d="M150 90 L157 72 L164 90 Z"/>
  </g>
</svg>`;
const SAYING = {
  island: ["watering the garden", "waking up the ducks", "milking the cows", "fluffing the sheep", "lighting the lanterns", "warming up the oven", "growing the willow a little"],
  diary: ["turning the pages", "finding our place", "dusting off the memories"],
};
function portalOpen(text, kind = "island") {
  const r = switchBtn.getBoundingClientRect();
  const visible = r.width > 0 && r.height > 0;
  const el = document.createElement("div");
  el.className = `g3d-portal is-${kind}`;
  el.style.setProperty("--px", `${visible ? r.left + r.width / 2 : innerWidth / 2}px`);
  el.style.setProperty("--py", `${visible ? r.top + r.height / 2 : innerHeight / 2}px`);
  // a sky of twinkling stars and drifting clouds
  for (let i = 0; i < 26; i++) {
    const st = document.createElement("b");
    st.className = "g3d-portal-star";
    st.style.cssText = `left:${Math.random() * 100}%;top:${Math.random() * 100}%;--t:${(1.6 + Math.random() * 2.4).toFixed(2)}s;--s:${(0.5 + Math.random()).toFixed(2)}`;
    el.append(st);
  }
  for (let i = 0; i < 3; i++) {
    const c = document.createElement("span");
    c.className = "g3d-portal-cloud";
    c.style.cssText = `top:${18 + i * 26}%;--dur:${16 + i * 6}s;--delay:${-i * 5}s;--sc:${1 - i * 0.2}`;
    el.append(c);
  }
  const art = document.createElement("div");
  art.className = "g3d-portal-art";
  art.innerHTML = ISLAND_SVG;
  const label = document.createElement("p");
  label.className = "g3d-portal-title";
  [...text].forEach((ch, i) => {
    const sp = document.createElement("span");
    sp.textContent = ch;
    sp.style.setProperty("--i", i);
    label.append(sp);
  });
  const sub = document.createElement("p");
  sub.className = "g3d-portal-sub";
  const says = SAYING[kind] || SAYING.island;
  let k = Math.floor(Math.random() * says.length);
  sub.textContent = `${says[k]}…`;
  const tick = setInterval(() => {
    k = (k + 1) % says.length;
    sub.classList.remove("swap");
    void sub.offsetWidth;
    sub.classList.add("swap");
    sub.textContent = `${says[k]}…`;
  }, 1500);
  el._tick = tick;
  const dots = document.createElement("div");
  dots.className = "g3d-portal-dots";
  dots.innerHTML = "<span></span><span></span><span></span>";
  el.append(art, label, sub, dots);
  for (let i = 0; i < 14; i++) {
    const sp = document.createElement("i");
    sp.style.setProperty("--a", `${(i / 14) * 360}deg`);
    sp.style.setProperty("--d", `${(i % 3) * 0.08}s`);
    el.append(sp);
  }
  document.body.append(el);
  // two frames so the start state is painted before it opens
  requestAnimationFrame(() => requestAnimationFrame(() => el.classList.add("open")));
  return wait(reduceMotion() ? 180 : 620).then(() => el);
}
function portalClose(el) {
  if (!el) return;
  clearInterval(el._tick);
  el.classList.add("leave");
  setTimeout(() => el.remove(), reduceMotion() ? 200 : 750);
}
// the island shows its own loading card first; the portal waits for it to finish
async function islandReady(timeout = 8000) {
  const t0 = performance.now();
  while (performance.now() - t0 < timeout) {
    const card = document.querySelector(".g3d-loading");
    if (!card || card.classList.contains("done")) return;
    await wait(80);
  }
}

async function enter(opts = {}) {
  if (game || starting) return;
  if (!webglOK()) {
    alert("this device can’t show the 3D world, so the classic site stays on");
    return;
  }
  saveMode("3d");
  starting = import("./island.js");
  syncSwitch();
  const portal = await (opts.portal || portalOpen("to our island", "island"));
  try {
    // what the other devices saved comes in before the world reads it
    const [{ startGame }] = await Promise.all([starting, opts.guest ? null : pullGameSaves()]);
    game = startGame({ onExit: exit, guest: opts.guest || null });
    await islandReady();
  } catch (error) {
    console.error("3D world failed to start", error);
    document.querySelectorAll("#game3d, .g3d-panel-frame, .g3d-overlay, .g3d-fade, .g3d-loading").forEach((el) => el.remove());
    document.documentElement.classList.remove("g3d-on", "g3d-focus");
    saveMode("2d");
  } finally {
    starting = null;
    syncSwitch();
    portalClose(portal);
  }
}

let leaving = false;
async function exit() {
  if (!game || leaving) return;
  leaving = true;
  saveMode("2d");
  const portal = await portalOpen("back to our diary", "diary");
  game?.destroy();
  game = null;
  syncSwitch();
  window.scrollTo(0, 0);
  leaving = false;
  portalClose(portal);
}

function mountSwitch() {
  const actions = document.querySelector(".toolbar-actions");
  if (!actions) return;
  const search = document.getElementById("searchToggleBtn");
  actions.insertBefore(switchBtn, search && search.parentElement === actions ? search : actions.firstChild);
  syncSwitch();
}

function whenBooted(fn) {
  if (!document.body.classList.contains("app-booting")) return fn();
  const mo = new MutationObserver(() => {
    if (!document.body.classList.contains("app-booting")) {
      mo.disconnect();
      fn();
    }
  });
  mo.observe(document.body, { attributes: true, attributeFilter: ["class"] });
}

mountSwitch();
if (guestInfo) {
  // a visitor link: the island's loading sky goes up straight away, so the site's sign-in
  // never shows while the link is checked (members just go in; visitors get a look-only
  // island). The same sky carries on into the island.
  const ok = !guestInfo.bad && !guestInfo.expired && webglOK();
  const sky = ok ? portalOpen("to our island", "island") : null;
  if (ok) document.documentElement.classList.add("g3d-guest-wait");
  const refuse = async (text) => {
    document.documentElement.classList.remove("g3d-guest-wait");
    if (sky) portalClose(await sky);
    showNote(text);
  };
  whenBooted(() => {
    if (window.__tddBridge?.getUser?.()) {
      document.documentElement.classList.remove("g3d-guest-wait");
      enter({ portal: sky });
      return;
    }
    if (!ok) {
      showNote(guestInfo.expired ? "this visitor link has ended ♡ ask for a new one" : "this visitor link doesn't look right ♡");
      return;
    }
    // a link ended early never opens the island at all
    checkGuest(guestInfo.token, window.__tddBridge?.supabase).then((verdict) => {
      if (verdict === "denied") return refuse("this visitor link has ended ♡ ask for a new one");
      document.documentElement.classList.add("g3d-guest");
      document.documentElement.classList.remove("g3d-guest-wait");
      enter({ guest: guestInfo, portal: sky });
    });
  });
} else if (readMode() === "3d" && webglOK()) whenBooted(enter);

function showNote(text) {
  const card = document.createElement("div");
  card.className = "g3d-invite-card";
  const p = document.createElement("p");
  p.textContent = text;
  const ok = document.createElement("button");
  ok.type = "button";
  ok.className = "yes";
  ok.textContent = "okay";
  ok.onclick = () => card.remove();
  const row = document.createElement("div");
  row.append(ok);
  card.append(p, row);
  document.body.append(card);
}

// ---- invites: a small always-on lobby (works in the classic site too) ------
const LOBBY = "tdd3d-lobby";
let lobby = null;
let lobbyKey = "";
function lobbyName() {
  return window.__tddBridge?.getMyName?.() || "";
}
function connectLobby() {
  if (lobby) return;
  const bridge = window.__tddBridge;
  const user = bridge?.getUser?.();
  if (!bridge?.supabase || !user) return;
  lobbyKey = `${user.id}:${Math.random().toString(36).slice(2, 8)}`;
  const ch = bridge.supabase.channel(LOBBY, { config: { broadcast: { self: false }, presence: { key: lobbyKey } } });
  lobby = ch;
  ch.on("broadcast", { event: "invite" }, ({ payload }) => {
    if (!payload || payload.fromUser === user.id) return;
    showInvite(payload.name || "your person");
  });
  ch.subscribe((status) => {
    if (status === "SUBSCRIBED") ch.track({ user: user.id, name: lobbyName() }).catch(() => {});
  });
  window.__tddLobby = {
    others: () =>
      Object.entries(ch.presenceState())
        .filter(([key]) => !key.startsWith(`${user.id}:`))
        .map(([, metas]) => metas[0] || {}),
    invite: (name) => ch.send({ type: "broadcast", event: "invite", payload: { fromUser: user.id, name } }).catch?.(() => {}),
  };
  // keep the shown name fresh once the profile has loaded
  setTimeout(() => ch.track({ user: user.id, name: lobbyName() }).catch(() => {}), 5000);
}
function showInvite(name) {
  document.querySelector(".g3d-invite-card")?.remove();
  const card = document.createElement("div");
  card.className = "g3d-invite-card";
  card.setAttribute("role", "alertdialog");
  const p = document.createElement("p");
  p.textContent = `💌 ${name} invited you to the island ♡`;
  const row = document.createElement("div");
  const later = document.createElement("button");
  later.type = "button";
  later.textContent = "later";
  later.onclick = () => card.remove();
  const yes = document.createElement("button");
  yes.type = "button";
  yes.className = "yes";
  yes.textContent = "join ♡";
  yes.onclick = () => {
    card.remove();
    if (game) window.dispatchEvent(new CustomEvent("tdd3d:meet"));
    else {
      try {
        sessionStorage.setItem("tdd3d.meet", "1");
      } catch {}
      enter();
    }
  };
  row.append(later, yes);
  card.append(p, row);
  document.body.append(card);
  navigator.vibrate?.([40, 60, 40]);
  setTimeout(() => card.remove(), 60000);
}
setInterval(connectLobby, 3000);
document.addEventListener("visibilitychange", () => {
  if (document.hidden) flushGameSaves();
});
