// Keeps everything the 3D world saves (your look, the pet, paintings, the
// album, scores, music, day or night...) the same on every phone and
// computer. Every "tdd3d." setting is mirrored into one hidden widgets row
// per person, beside the diary's own synced prefs; whichever device changed
// a setting last wins. What we make together (paintings, the willow, the
// photo wall...) is kept for both of us instead: see shared.js.
import { isShared, offerShared, sharedSaved, pullShared, flushShared } from "./shared.js";

const PREFIX = "tdd3d.";
const STAMPS_KEY = "tdd3dSyncStamps";
const rowId = (userId) => `__prefs:game:${userId}`;

let applying = false;
let pushTimer = 0;
let patched = false;

const bridge = () => window.__tddBridge;
const userId = () => bridge()?.getUser?.()?.id || "";

function readStamps() {
  try {
    const parsed = JSON.parse(localStorage.getItem(STAMPS_KEY) || "{}");
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}
function writeStamps(stamps) {
  try {
    localStorage.setItem(STAMPS_KEY, JSON.stringify(stamps));
  } catch {}
}
function localKeys() {
  const keys = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key?.startsWith(PREFIX) && !isShared(key)) keys.push(key);
  }
  return keys;
}

// every write to a tdd3d. key is stamped and sent up a moment later
function watchWrites() {
  if (patched) return;
  patched = true;
  const proto = Storage.prototype;
  const setItem = proto.setItem;
  const removeItem = proto.removeItem;
  const touched = (storage, key) => {
    if (applying || storage !== localStorage || !String(key).startsWith(PREFIX) || isShared(key)) return;
    const stamps = readStamps();
    stamps[key] = Date.now();
    writeStamps(stamps);
    schedulePush();
  };
  proto.setItem = function (key, value) {
    setItem.call(this, key, value);
    touched(this, key);
  };
  proto.removeItem = function (key) {
    removeItem.call(this, key);
    touched(this, key);
  };
}

async function fetchRow(id) {
  const { data, error } = await bridge().supabase.from("widgets").select("data").eq("id", id).maybeSingle();
  if (error) throw error;
  const d = data?.data;
  return {
    values: d?.values && typeof d.values === "object" ? d.values : {},
    stamps: d?.stamps && typeof d.stamps === "object" ? d.stamps : {},
  };
}

// folds the saved copy into this device; returns true when this device has
// something newer that should go up
function merge(cloud) {
  const stamps = readStamps();
  let newerHere = false;
  applying = true;
  try {
    for (const [key, cloudStamp] of Object.entries(cloud.stamps)) {
      if (!key.startsWith(PREFIX)) continue;
      // an older backup of something we share: the shared copy decides
      if (isShared(key)) {
        offerShared(key, cloud.values[key], cloudStamp);
        continue;
      }
      if ((stamps[key] || 0) >= cloudStamp) continue;
      const value = cloud.values[key];
      if (value == null) localStorage.removeItem(key);
      else localStorage.setItem(key, value);
      stamps[key] = cloudStamp;
    }
  } finally {
    applying = false;
  }
  const now = Date.now();
  for (const key of localKeys()) {
    // saved here before syncing existed: send it up unless the cloud has one
    if (!stamps[key] && !(key in cloud.stamps)) stamps[key] = now;
    if ((stamps[key] || 0) > (cloud.stamps[key] || 0)) newerHere = true;
  }
  for (const [key, stamp] of Object.entries(stamps)) {
    if (isShared(key)) continue;
    if (!(key in cloud.stamps) && localStorage.getItem(key) == null && stamp) newerHere = true;
  }
  writeStamps(stamps);
  return newerHere;
}

async function push() {
  pushTimer = 0;
  const uid = userId();
  if (!uid) return;
  const id = rowId(uid);
  try {
    const cloud = await fetchRow(id);
    merge(cloud);
    const stamps = readStamps();
    const values = {};
    for (const key of Object.keys(stamps)) {
      if (isShared(key)) delete stamps[key];
      else if (key.startsWith(PREFIX)) values[key] = localStorage.getItem(key);
    }
    // keep the old backup of shared things until the shared copy is safely saved
    for (const [key, stamp] of Object.entries(cloud.stamps)) {
      if (isShared(key) && !sharedSaved(key) && cloud.values[key] != null) {
        values[key] = cloud.values[key];
        stamps[key] = stamp;
      }
    }
    const now = new Date().toISOString();
    const payload = { title: "__prefs", side: "left", x: 0, y: 0, content: null, updated_at: now, data: { values, stamps, updatedAt: now } };
    const sb = bridge().supabase;
    const { data: rows, error } = await sb.from("widgets").update(payload).eq("id", id).select("id");
    if (error) throw error;
    if (!rows?.length) {
      const { error: insertError } = await sb.from("widgets").insert({ id, ...payload });
      if (insertError) throw insertError;
    }
  } catch (error) {
    console.warn("3D world sync failed", error);
  }
}

function schedulePush() {
  clearTimeout(pushTimer);
  pushTimer = setTimeout(push, 3000);
}

// before the world starts: bring in what the other devices saved
export async function pullGameSaves({ timeout = 5000 } = {}) {
  watchWrites();
  const uid = userId();
  if (!uid || !bridge()?.supabase) return;
  const work = fetchRow(rowId(uid))
    .then((cloud) => {
      if (merge(cloud)) schedulePush();
    })
    .catch((error) => console.warn("3D world sync failed", error))
    // then what we share (if it comes late, the island updates when it lands)
    .then(() => pullShared())
    .catch((error) => console.warn("island saves failed to load", error));
  await Promise.race([work, new Promise((r) => setTimeout(r, timeout))]);
}

// send anything waiting before the page goes away
export function flushGameSaves() {
  flushShared();
  if (!pushTimer) return;
  clearTimeout(pushTimer);
  pushTimer = 0;
  void push();
}
